36	/**
37	 * Abstract execution context.
38	 * All regular DBCExecutionContext implementations should extend this class.
39	 * It provides bootstrap init functions and QM notifications.
40	 */
41	public abstract class AbstractExecutionContext<DATASOURCE extends DBPDataSource, INSTANCE extends DBSInstance>
42	    implements DBCExecutionContext {
43	    private static final Log log = Log.getLog(AbstractExecutionContext.class);
44	
45	    private static long idSequence = 0;
46	
47	    @NotNull
48	    protected INSTANCE instance;
49	    @NotNull
50	    protected final DATASOURCE dataSource;
51	    protected final String purpose;
52	    protected final long id;
53	    private final Map<String, Object> contextAttributes = new LinkedHashMap<>();
54	
55	    public AbstractExecutionContext(@NotNull INSTANCE instance, String purpose) {
56	        this.instance = instance;
57	        this.dataSource = (DATASOURCE) instance.getDataSource();
58	        this.purpose = purpose;
59	        this.id = generateContextId();
60	
61	        log.debug("Execution context opened (" + dataSource.getName() + "; " + purpose + "; " + this.id +  ")");
62	
63	        QMUtils.getDefaultHandler().handleContextOpen(this, false);
64	    }
65	
66	    public static synchronized long generateContextId() {
67	        return idSequence++;
68	    }
69	
70	    @NotNull
71	    @Override
72	    public INSTANCE getOwnerInstance() {
73	        return instance;
74	    }
75	
76	    protected void setOwnerInstance(@NotNull INSTANCE instance) {
77	        this.instance = instance;
78	    }
79	
80	    @Override
81	    public long getContextId() {
82	        return this.id;
83	    }
84	
85	    @NotNull
86	    @Override
87	    public String getContextName() {
88	        return purpose;
89	    }
90	
91	    @NotNull
92	    @Override
93	    public DATASOURCE getDataSource() {
94	        return dataSource;
95	    }
96	
97	    @Nullable
98	    @Override
99	    public DBCExecutionContextDefaults getContextDefaults() {
100	        return null;
101	    }
102	
103	    @NotNull
104	    protected DBPConnectionBootstrap getBootstrapSettings() {
105	        return getDataSource().getContainer().getActualConnectionConfiguration().getBootstrap();
106	    }
107	
108	    /**
109	     * Context boot procedure.
110	     * Executes bootstrap queries and other init functions.
111	     * This function must be called by all implementations.
112	     */
113	    protected boolean initContextBootstrap(@NotNull DBRProgressMonitor monitor, boolean autoCommit) throws DBException {
114	        // Notify QM
115	        QMUtils.getDefaultHandler().handleContextUpdate(this, !autoCommit);
116	
117	        // Execute bootstrap queries
118	        DBPConnectionBootstrap bootstrap = getBootstrapSettings();
119	        List<String> initQueries = bootstrap.getInitQueries();
120	        if (!CommonUtils.isEmpty(initQueries)) {
121	            monitor.subTask("Run bootstrap queries");
122	            try (DBCSession session = openSession(monitor, DBCExecutionPurpose.UTIL, "Run bootstrap queries")) {
123	                for (String query : initQueries) {
124	                    // Replace variables
125	                    query = GeneralUtils.replaceVariables(query, getDataSource().getContainer().getVariablesResolver(true));
126	                    try {
127	                        try (DBCStatement dbStat = session.prepareStatement(DBCStatementType.SCRIPT, query, false, false, false)) {
128	                            dbStat.executeStatement();
129	                        }
130	                    } catch (Exception e) {
131	                        String message = "Error executing bootstrap query: " + query;
132	                        if (bootstrap.isIgnoreErrors()) {
133	                            log.warn(message);
134	                        } else {
135	                            throw new DBCException(message, e, this);
136	                        }
137	                    }
138	                }
139	            }
140	            return true;
141	        }
142	        return false;
143	    }
144	
145	    protected void closeContext()
146	    {
147	        QMUtils.getDefaultHandler().handleContextClose(this);
148	
149	        log.debug("Execution context closed (" + dataSource.getName() + ", " + this.id +  ")");
150	    }

